import os
import random
import string
from typing import List, Tuple

# This generator focuses on producing valid, interesting pairs of
# (environment variable name, value) encoded into a single bytes buffer.
# The target fuzzers call FUZZ_PARAM_STR twice (name, value). Our buffer
# therefore concatenates two NUL-terminated C-strings: name\0value\0.
#
# Constraints derived from stubs:
# - Names and values must be non-empty.
# - Names should look like environment variable identifiers.
# - Values can include typical patterns (paths, locales, numbers, quoted strings,
#   booleans, colon-separated lists, UTF-8 text, etc.).
# - Keep total length under 4096 bytes.
#
# The seed controls randomized choices to diversify yet keep validity.

MAX_TOTAL = 4096

UPPER = string.ascii_uppercase
DIGITS = string.digits
UNDERSCORE = "_"

# A curated set of common/interesting env var names used by shells, locales,
# SSH, and general UNIX environments.
COMMON_NAMES = [
    "PATH", "HOME", "LANG", "LC_ALL", "LC_CTYPE", "TERM", "SHELL",
    "USER", "LOGNAME", "TMPDIR", "EDITOR", "VISUAL", "PAGER", "MAIL",
    "TZ", "PWD", "OLDPWD", "SHLVL", "COLORTERM", "XDG_RUNTIME_DIR",
    "XDG_SESSION_TYPE", "XDG_DATA_DIRS", "XDG_CONFIG_HOME", "XDG_CACHE_HOME",
    "GIT_SSH_COMMAND", "SSH_AUTH_SOCK", "SSH_ASKPASS", "SSH_TTY",
    "SSH_CONNECTION", "SSH_CLIENT", "SSH_ORIGINAL_COMMAND",
    "LANGUAGE", "LC_NUMERIC", "LC_TIME", "LC_COLLATE", "LC_MONETARY",
    "LC_MESSAGES", "LC_PAPER", "LC_NAME", "LC_ADDRESS", "LC_TELEPHONE",
    "LC_MEASUREMENT", "LC_IDENTIFICATION",
    # Some plausible app-specific envs to exercise arbitrary names
    "APP_MODE", "DEBUG", "FEATURE_FLAGS", "REQUEST_ID", "TRACE_ID",
    "NO_PROXY", "HTTP_PROXY", "HTTPS_PROXY",
]

# Values to combine and synthesize from
PATH_DIRS = [
    "/usr/local/sbin", "/usr/local/bin", "/usr/sbin", "/usr/bin",
    "/sbin", "/bin", "/opt/bin", "/snap/bin", "/usr/games",
]
LOCALES = [
    "C", "POSIX", "en_US.UTF-8", "C.UTF-8", "de_DE.UTF-8",
    "fr_FR.UTF-8", "ja_JP.UTF-8", "ru_RU.UTF-8", "zh_CN.UTF-8",
]
TERMS = ["xterm", "xterm-256color", "vt100", "linux", "screen-256color"]
SHELLS = ["/bin/bash", "/bin/sh", "/usr/bin/zsh", "/usr/bin/fish"]
BOOLS = ["0", "1", "true", "false", "True", "False", "YES", "NO"]
MISC_VALUES = [
    "utf-8", "ASCII", "en_GB", "production", "staging", "development",
    "info", "debug", "warn", "error", "TRACE", "INFO", "DEBUG",
    "x86_64", "arm64", "aarch64", "Windows_NT", "Linux",
]
COOKIES = [
    "0123456789abcdef0123456789abcdef",  # hex cookie
    "AAABBBCCC111222333DDD==",            # base64-like
]
PROTOCOLS = ["MIT-MAGIC-COOKIE-1", "XDM-AUTHORIZATION-1"]

UNICODE_FRAGMENTS = [
    "こんにちは", "Привет", "مرحبا", "γειά", "नमस्ते", "안녕하세요",
    "שלום", "สวัสดี", "Olá", "¡Hola!", "Cześć", "Γειά σου",
]

# Generate a valid environment variable name per typical rules:
# - First char: letter or underscore
# - Subsequent: letters, digits, underscore
# - Prefer uppercase for broad compatibility

def gen_env_name(rng: random.Random) -> str:
    # Mix between known names and synthesized names
    if rng.random() < 0.6:
        return rng.choice(COMMON_NAMES)
    # Synthesize
    length = rng.randint(3, 24)
    first = rng.choice(UPPER + UNDERSCORE)
    rest_chars = UPPER + DIGITS + UNDERSCORE
    rest = "".join(rng.choice(rest_chars) for _ in range(length - 1))
    # Occasionally insert digits in the middle to vary patterns
    if rng.random() < 0.4 and length > 4:
        i = rng.randint(1, length - 2)
        rest = rest[:i] + rng.choice(DIGITS) + rest[i + 1 :]
    return first + rest


def gen_path_like(rng: random.Random) -> str:
    # Join random selection of directories with ':'
    dirs = PATH_DIRS[:]
    rng.shuffle(dirs)
    k = rng.randint(2, min(6, len(dirs)))
    return ":".join(dirs[:k])


def gen_locale(rng: random.Random) -> str:
    return rng.choice(LOCALES)


def gen_term(rng: random.Random) -> str:
    return rng.choice(TERMS)


def gen_shell(rng: random.Random) -> str:
    return rng.choice(SHELLS)


def gen_cookie(rng: random.Random) -> str:
    proto = rng.choice(PROTOCOLS)
    cookie = rng.choice(COOKIES)
    screen = str(rng.randint(0, 9))
    return f"{proto};{cookie};{screen}"


def gen_proxy_url(rng: random.Random) -> str:
    # Basic proxy URL formats
    scheme = rng.choice(["http", "https", "socks5"])
    host = rng.choice(["127.0.0.1", "localhost", "10.0.0.1"])  # simple, valid
    port = rng.choice(["1080", "3128", "8080", "8888"])  # common proxy ports
    if rng.random() < 0.5:
        user = rng.choice(["user", "admin", "u1"])  # no special chars
        pwd = rng.choice(["pass", "secret", "p@ss"])
        auth = f"{user}:{pwd}@"
    else:
        auth = ""
    return f"{scheme}://{auth}{host}:{port}"


def gen_value_for_name(name: str, rng: random.Random) -> str:
    upper = name.upper()
    if upper == "PATH":
        return gen_path_like(rng)
    if upper in ("LANG", "LC_ALL", "LC_CTYPE", "LANGUAGE",
                 "LC_NUMERIC", "LC_TIME", "LC_COLLATE", "LC_MONETARY",
                 "LC_MESSAGES", "LC_PAPER", "LC_NAME", "LC_ADDRESS",
                 "LC_TELEPHONE", "LC_MEASUREMENT", "LC_IDENTIFICATION"):
        return gen_locale(rng)
    if upper == "TERM":
        return gen_term(rng)
    if upper in ("SHELL",):
        return gen_shell(rng)
    if upper in ("SSH_AUTH_SOCK",):
        # plausible UNIX socket path
        base = rng.choice(["/run/user/1000/ssh-agent.sock", "/tmp/ssh-XXXXXX/agent.1234"]) 
        return base
    if upper in ("SSH_ASKPASS",):
        return rng.choice(["/usr/bin/ssh-askpass", "/usr/lib/ssh/ssh-askpass"])
    if upper in ("SSH_TTY",):
        return rng.choice(["/dev/pts/0", "/dev/tty1", "/dev/pts/3"])
    if upper in ("SSH_ORIGINAL_COMMAND",):
        return rng.choice(["/bin/ls -la", "whoami", "echo hello"])    
    if upper in ("HTTP_PROXY", "HTTPS_PROXY"):
        return gen_proxy_url(rng)
    if upper == "NO_PROXY":
        # comma-separated list of hosts
        hosts = ["localhost", "127.0.0.1", ".example.com", "10.0.0.0/8"]
        rng.shuffle(hosts)
        return ",".join(hosts[: rng.randint(1, len(hosts))])
    if upper in ("DEBUG",):
        return rng.choice(BOOLS)
    if upper in ("APP_MODE",):
        return rng.choice(["production", "staging", "development", "test"])
    if upper in ("REQUEST_ID", "TRACE_ID"):
        # simple hex-ish identifier
        length = rng.randint(8, 32)
        return "".join(rng.choice(string.hexdigits.lower()) for _ in range(length))
    if upper in ("COLORTERM",):
        return rng.choice(["truecolor", "24bit", "256color"]) 
    if upper in ("XDG_RUNTIME_DIR",):
        return "/run/user/1000"
    if upper in ("XDG_SESSION_TYPE",):
        return rng.choice(["tty", "x11", "wayland", "unknown"])
    if upper in ("XDG_DATA_DIRS",):
        return ":".join(["/usr/local/share", "/usr/share"])    
    if upper in ("TMPDIR",):
        return rng.choice(["/tmp", "/var/tmp", "/run/user/1000"]) 
    if upper in ("MAIL",):
        return "/var/mail/user"
    if upper in ("PAGER",):
        return rng.choice(["less", "more", "cat"]) 
    if upper in ("EDITOR", "VISUAL"):
        return rng.choice(["vim", "nano", "code", "ed"]) 
    if upper in ("TZ",):
        return rng.choice(["UTC", "Europe/Prague", "America/New_York"]) 
    if upper in ("HOME", "PWD", "OLDPWD"):
        return "/home/user" if upper != "OLDPWD" else "/home/user/old"
    if upper in ("GIT_SSH_COMMAND",):
        return "ssh -o StrictHostKeyChecking=no"
    if upper in ("TERM_PROGRAM",):
        return rng.choice(["tmux", "screen", "iTerm.app"]) 
    if upper in ("XAUTHORITY",):
        return "/home/user/.Xauthority"
    if upper in ("DISPLAY",):
        return rng.choice([":0", ":1", "localhost:10.0"]) 
    if upper in ("XDG_CACHE_HOME", "XDG_CONFIG_HOME"):
        return "/home/user/.cache" if upper == "XDG_CACHE_HOME" else "/home/user/.config"
    if upper in ("SSH_CONNECTION", "SSH_CLIENT"):
        return rng.choice(["10.0.2.2 52714 10.0.2.15 22", "192.168.1.5 55555 192.168.1.10 22"]) 

    # For unknown names, synthesize varied but valid values.
    choice = rng.random()
    if choice < 0.2:
        return gen_path_like(rng)
    if choice < 0.35:
        return rng.choice(LOCALES)
    if choice < 0.5:
        return rng.choice(BOOLS)
    if choice < 0.65:
        # quoted or spaced string
        base = rng.choice(["alpha", "beta", "gamma", "delta"]) 
        if rng.random() < 0.5:
            return f'"{base} {rng.randint(1, 99)}"'
        return f"{base} {rng.randint(1, 99)}"
    if choice < 0.8:
        # unicode rich
        frag = rng.choice(UNICODE_FRAGMENTS)
        return f"note:{frag}"
    if choice < 0.9:
        return rng.choice(MISC_VALUES)
    # X11-like cookie to tick different parsers
    return gen_cookie(rng)


def pack_c_strings(name: str, value: str) -> bytes:
    # Ensure non-empty and within size limits
    if not name:
        name = "X"
    if not value:
        value = "1"
    data = name.encode("utf-8", errors="strict") + b"\x00" + value.encode("utf-8", errors="strict") + b"\x00"
    # Truncate conservatively if needed
    if len(data) > MAX_TOTAL:
        # Reserve at least a byte for each NUL
        half = (MAX_TOTAL - 2) // 2
        n = name.encode("utf-8")[:half]
        v = value.encode("utf-8")[:half]
        data = n + b"\x00" + v + b"\x00"
    return data


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Create either a single pair or occasionally multiple pairs concatenated,
    # because some consumers might read until NULs or split repeatedly. The
    # individual fuzzers consume two strings; extra data is harmless and can
    # be used by other stubs in the corpus.
    pairs: List[Tuple[str, str]] = []
    num_pairs = 1 if rng.random() < 0.8 else rng.randint(2, 5)

    for _ in range(num_pairs):
        name = gen_env_name(rng)
        value = gen_value_for_name(name, rng)
        # Ensure non-empty due to fuzzer preconditions
        if not name:
            name = "ENV"
        if not value:
            value = "1"
        pairs.append((name, value))

    out = bytearray()
    for name, value in pairs:
        out += pack_c_strings(name, value)
        if len(out) >= MAX_TOTAL:
            break

    # Guarantee non-empty output
    if not out:
        out = pack_c_strings("ENV", "1")

    # Cap size
    return bytes(out[:MAX_TOTAL])
